SELECT 
  session_id, 
  gmt_msg_gen, 
  is_from_phx_host, 
  valid_payload,
  get_json_object(msg_extension, '$.PHXExtensionOrderStatus') AS order_status
FROM ba_phx.phx_mdw_detail_message_sync
WHERE dt BETWEEN '20260623' AND '20260629'
  AND session_id IN ('367827473','367798336','367817280','367928108','367799650','367812499','367837343','367885346','367848160','367779318','367880409','367964502','367803573','367794261','367916339','367794105','367820450','367929496','367780519','367964194','366843494','367836910','367907655','367868297','367809980','367849291','367901985','367916312','367801015','367787858','367842139','367922438','367951926','367915376','367781264','367791551','367917197','367848671','367844978','367849599','367863957','367959530','367784524','367845871','366158923','367798913','367799689','367111328','367799342','367869541')
ORDER BY session_id, gmt_msg_gen